import numpy as np

n = 20
qr = QuantumRegister(n, 'q')
cr = ClassicalRegister(n, 'c')
qc = QuantumCircuit(qr, cr)

rng = np.random.default_rng(42)

operations = []
for _ in range(60):
    gate = rng.choice(['rx', 'ry', 'rz', 'cx'])
    if gate == 'cx':
        control, target = rng.choice(n, size=2, replace=False)
        operations.append(('cx', int(control), int(target)))
    else:
        qubit = int(rng.integers(0, n))
        angle = float(rng.uniform(0, 2 * np.pi))
        operations.append((gate, angle, qubit))

for op in operations:
    if op[0] == 'cx':
        qc.cx(qr[op[1]], qr[op[2]])
    elif op[0] == 'rx':
        qc.rx(op[1], qr[op[2]])
    elif op[0] == 'ry':
        qc.ry(op[1], qr[op[2]])
    elif op[0] == 'rz':
        qc.rz(op[1], qr[op[2]])

for i in range(n):
    qc.measure(qr[i], cr[i])
